use std::rc::Rc;
const BITS: u32 = 5; const B: usize = 32; const MASK: usize = 31;
enum Node<T> { Inner(Vec<Rc<Node<T>>>), Leaf(Vec<T>) }
impl<T> Node<T> {
    fn inner(&self) -> &Vec<Rc<Node<T>>> { match self { Node::Inner(v)=>v, _=>panic!("inner") } }
    fn leaf(&self) -> &Vec<T> { match self { Node::Leaf(v)=>v, _=>panic!("leaf") } }
}
fn new_path<T>(level: u32, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
    if level == 0 { leaf } else { Rc::new(Node::Inner(vec![new_path(level-BITS, leaf)])) }
}
fn push_leaf<T>(node: &Rc<Node<T>>, level: u32, tail_off: usize, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
    let idx = (tail_off >> level) & MASK;
    let mut ch = node.inner().clone();
    if idx < ch.len() { let c = push_leaf(&ch[idx], level-BITS, tail_off, leaf); ch[idx] = c; }
    else { assert_eq!(idx, ch.len()); ch.push(new_path(level-BITS, leaf)); }
    Rc::new(Node::Inner(ch))
}
pub struct Vector<T> { root: Rc<Node<T>>, tail: Rc<Node<T>>, size: usize, shift: u32 }
impl<T: Clone> Vector<T> {
    pub fn new() -> Self { Vector{ root: Rc::new(Node::Inner(Vec::new())), tail: Rc::new(Node::Leaf(Vec::new())), size:0, shift:BITS } }
    pub fn size(&self) -> usize { self.size }
    fn tail_off(&self) -> usize { self.size - self.tail.leaf().len() }
    pub fn push_back(&self, x: T) -> Self {
        let tl = self.tail.leaf().len();
        if tl < B {
            let mut t = self.tail.leaf().clone(); t.push(x);
            Vector{ root:self.root.clone(), tail:Rc::new(Node::Leaf(t)), size:self.size+1, shift:self.shift }
        } else {
            let toff = self.size - B;
            let leaf = self.tail.clone();
            let (r,s) = if (toff >> BITS) + 1 > (1usize << self.shift) {
                (Rc::new(Node::Inner(vec![self.root.clone(), new_path(self.shift, leaf)])), self.shift+BITS)
            } else { (push_leaf(&self.root, self.shift, toff, leaf), self.shift) };
            Vector{ root:r, tail:Rc::new(Node::Leaf(vec![x])), size:self.size+1, shift:s }
        }
    }
    fn leaf_for(&self, i: usize) -> (&[T], usize) {
        let toff = self.tail_off();
        if i >= toff { return (self.tail.leaf(), toff); }
        let mut n = &self.root; let mut lvl = self.shift;
        while lvl > 0 { n = &n.inner()[(i >> lvl) & MASK]; lvl -= BITS; }
        (n.leaf(), i & !MASK)
    }
    pub fn get(&self, i: usize) -> &T { assert!(i < self.size); let (l,b)=self.leaf_for(i); &l[i-b] }
    pub fn iter(&self) -> Iter<'_, T> { Iter{ v:self, i:0, leaf:&[], base:0, end:0 } }
}
pub struct Iter<'a,T>{ v:&'a Vector<T>, i:usize, leaf:&'a [T], base:usize, end:usize }
impl<'a,T:Clone> Iterator for Iter<'a,T> {
    type Item=&'a T;
    fn next(&mut self)->Option<&'a T>{
        if self.i>=self.v.size { return None; }
        if self.i>=self.end { let (l,b)=self.v.leaf_for(self.i); self.leaf=l; self.base=b; self.end=b+l.len(); }
        let r=&self.leaf[self.i-self.base]; self.i+=1; Some(r)
    }
}
fn main(){
    let n: i32 = std::env::args().nth(1).map(|s| s.parse().unwrap()).unwrap_or(11);
    let mut v = Vector::new();
    for i in 0..n { v = v.push_back(i.wrapping_add(1)); }
    let mut sum: i32 = 0;
    for x in v.iter() { sum = sum.wrapping_add(*x); }
    println!("{}", sum);
    let mut v2 = Vector::new();
    for i in 0..v.size() { v2 = v2.push_back(v.get(i).wrapping_mul(2)); }
    let mut s2: i32 = 0;
    for x in v2.iter() { s2 = s2.wrapping_add(*x); }
    println!("{}", s2);
}
EOF
